#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* decide has a typed call. A plain ask for money back
   prints 1, THINKTHEN_YES, at 0.99 */
const char *q = "Does the customer ask for a refund?";
const char *t = "Please refund my order. It arrived broken.";
thinkthen_answer a;
if (thinkthen_decide(tt, q, t, strlen(t), &a) == THINKTHEN_OK)
    printf("%d %.2f\n", a.outcome, a.probability);
